          student: {
            id:          r.id,
            name:        r.name || '',
            email:       r.email || '',
            idNumber:    r.mssv || '',
            dateOfBirth: r.dob  || '',
            gender:      r.gender || '',
          },
          studentNumber:  r.stt || null,
          attendanceRate: 0,           // placeholder — chưa có data attendance
          averageScore:   0,           // placeholder — sẽ tính từ StudentGrade sau
          totalXP:        0,
          completedExams: 0,
          passedExams:    0,
          status:         'active',
          enrollmentDate: r.createdAt,
